//go:build eval

// Prompt Eval: evaluates the coding-agent prompt generated by `ast project create`
// across a set of domain-expert scenarios using Claude as a grader.
//
// These tests are gated behind the eval build tag and are intentionally excluded
// from the normal CI test suite. They run on-demand or via the eval-prompt GitHub
// Action triggered on pull requests that touch the prompt or eval files.
//
// # Running
//
// Requires an Anthropic API key:
//
//	export ANTHROPIC_API_KEY=sk-ant-...
//	go test ./cmd/ -tags eval -run TestEval_Graded -v
//
// # Structural tests (no API key)
//
// The structural tests check prompt formatting and require the eval build tag:
//
//	go test ./cmd/ -tags eval -run TestBuildCodingPrompt_Structure -v
//
// # Adding scenarios
//
// Append to the `agentScenarios` slice. Each entry needs a kebab-case `name`
// and an optional `goal` string describing what the agent should do.
//
// # Grader
//
// The grader calls `claude-haiku-4-5` with a 1–10 rubric. It uses assistant
// prefill (seeding the response with "```json") and a stop sequence ("```") to
// extract clean JSON without post-processing. The test fails if any scenario
// scores below 5/10.
package cmd

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/anthropics/anthropic-sdk-go"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// agentScenario is one eval test case: a persona and an optional goal.
type agentScenario struct {
	name      string
	goal      string
	expectLow bool // true for edge cases expected to score below threshold
}

// evalResult holds the generated prompt and optional grade for one scenario.
type evalResult struct {
	Scenario agentScenario
	Prompt   string
	Grade    *promptGrade
}

// promptGrade is the LLM grader's verdict on a generated prompt.
type promptGrade struct {
	Score      int      `json:"score"`      // 1–10
	Strengths  []string `json:"strengths"`  // up to 3
	Weaknesses []string `json:"weaknesses"` // up to 3
	Reasoning  string   `json:"reasoning"`
}

// agentScenarios is the eval dataset — ten domain experts plus edge cases.
var agentScenarios = []agentScenario{
	{
		name: "security-analyst",
		goal: "monitor CVE feeds, triage vulnerabilities by severity against our dependency graph, and post a daily Slack digest with remediation suggestions for critical findings",
	},
	{
		name: "bioinformatics-researcher",
		goal: "query gene expression databases, identify differential expression patterns across sample groups, and generate publication-ready summary reports with visualisations",
	},
	{
		name: "legal-analyst",
		goal: "review uploaded contracts for non-standard clauses, flag deviations from our standard template, and produce a redline summary ranked by legal risk",
	},
	{
		name: "devops-engineer",
		goal: "watch Kubernetes cluster events, diagnose pod crash-loops using log context and recent deploys, and open a GitHub issue with root cause and remediation steps",
	},
	{
		name: "climate-scientist",
		goal: "ingest hourly weather station readings into a time-series knowledge base, detect anomalies using rolling baselines, and email weekly climate trend reports to subscribers",
	},
	{
		name: "supply-chain-manager",
		goal: "track real-time inventory levels across warehouses, predict stockouts using historical velocity, and automatically raise purchase orders when stock falls below dynamic reorder points",
	},
	{
		name: "financial-analyst",
		goal: "monitor earnings call transcripts and SEC filings, extract forward guidance signals, and surface alerts when sentiment diverges significantly from analyst consensus",
	},
	{
		name: "music-producer",
		goal: "analyse an uploaded audio stem, identify key, tempo, and harmonic structure, then suggest chord progressions and arrangement ideas that complement the source material",
	},
	{
		name: "archaeologist",
		goal: "cross-reference dig site artefact metadata with digitised museum catalogues and academic papers to identify provenance matches and flag items requiring further investigation",
	},
	{
		name: "content-moderator",
		goal: "review user-generated posts against community guidelines, classify violation type and severity, queue borderline cases for human review, and maintain an audit log of decisions",
	},
	// edge cases
	{name: "no-goal", goal: ""},
	{name: "gibberish-goal", goal: "flibbertigibbet the zorp until the meeples frazzle the whatsit machine and the snorkel blips", expectLow: true},
}

const gradingTask = `You are evaluating a prompt that will be given to a coding agent to help
implement an AI agent on the Astropods platform.

Scoring rubric (1–10):
 9-10 – Clear platform context, well-scoped agent purpose, actionable instructions,
         structured requirements gathering, no ambiguity.
 6-8  – Mostly clear with minor gaps in context or specificity.
 3-5  – Adequate but missing important context or vague about what the agent does.
 1-2  – Confusing, incoherent, or missing key instructions.

Evaluate the prompt below and respond with JSON covering:
- "score": integer 1–10
- "strengths": array of up to 3 short strings
- "weaknesses": array of up to 3 short strings
- "reasoning": one sentence explaining the score`

func runTestCase(s agentScenario) evalResult {
	return evalResult{
		Scenario: s,
		Prompt:   buildCodingPrompt(s.name, s.goal),
	}
}

func runEval(dataset []agentScenario) []evalResult {
	results := make([]evalResult, len(dataset))
	for i, s := range dataset {
		results[i] = runTestCase(s)
	}
	return results
}

// gradePrompt calls Claude to score a generated coding-agent prompt.
// Uses assistant prefill + stop sequence to reliably extract JSON.
// Returns an error so callers can log failures.
func gradePrompt(ctx context.Context, client anthropic.Client, result *evalResult) error {
	msg, err := client.Messages.New(ctx, anthropic.MessageNewParams{
		Model:         anthropic.ModelClaudeHaiku4_5,
		MaxTokens:     512,
		StopSequences: []string{"```"},
		Messages: []anthropic.MessageParam{
			anthropic.NewUserMessage(
				anthropic.NewTextBlock(gradingTask + "\n\nPrompt to evaluate:\n\n" + result.Prompt),
			),
			anthropic.NewAssistantMessage(anthropic.NewTextBlock("```json")),
		},
	})
	if err != nil {
		return fmt.Errorf("API call failed: %w", err)
	}
	if len(msg.Content) == 0 {
		return fmt.Errorf("API returned no content blocks")
	}
	raw := msg.Content[0].AsText().Text
	var g promptGrade
	if err := json.Unmarshal([]byte(raw), &g); err != nil {
		return fmt.Errorf("JSON parse failed (raw: %q): %w", raw, err)
	}
	result.Grade = &g
	return nil
}

// ── structural tests (no API key required) ────────────────────────────────────

func TestBuildCodingPrompt_Structure(t *testing.T) {
	for _, s := range agentScenarios {
		t.Run(s.name, func(t *testing.T) {
			prompt := buildCodingPrompt(s.name, s.goal)

			assert.Contains(t, prompt, "astropods.yml")
			assert.Contains(t, prompt, "**"+s.name+"**")
			assert.Contains(t, prompt, "gather requirements")
			assert.Contains(t, prompt, "Do not make assumptions")

			if s.goal != "" {
				assert.Contains(t, prompt, "Initial description")
				firstWord := strings.Fields(s.goal)[0]
				assert.Contains(t, prompt, firstWord)
			} else {
				assert.NotContains(t, prompt, "Initial description")
			}

			for line := range strings.SplitSeq(prompt, "\n") {
				assert.LessOrEqualf(t, len(line), 80,
					"line exceeds 80 chars: %q", line)
			}
		})
	}
}

// ── graded eval (requires ANTHROPIC_API_KEY) ─────────────────────────────────

func TestEval_Graded(t *testing.T) {
	if os.Getenv("ANTHROPIC_API_KEY") == "" {
		t.Fatal("ANTHROPIC_API_KEY not set")
	}
	// TODO: replace with an OpenAI-compatible HTTP client so the grader
	// can target any provider, including a self-hosted Astropods agent
	client := anthropic.NewClient()
	results := runEval(agentScenarios)

	for i := range results {
		if err := gradePrompt(t.Context(), client, &results[i]); err != nil {
			t.Logf("grader error for %q: %v", results[i].Scenario.name, err)
		}
	}

	t.Log("\n── Graded eval results ──────────────────────────────────────────")
	pass := true
	var total, graded int
	for _, r := range results {
		if r.Grade == nil {
			t.Logf("%-30s  grade: n/a (grader failed)", r.Scenario.name)
			continue
		}
		graded++
		total += r.Grade.Score
		marker := "✓"
		if r.Grade.Score < 5 && !r.Scenario.expectLow {
			marker = "✗"
			pass = false
		} else if r.Scenario.expectLow {
			marker = "~"
		}
		t.Logf("%-30s  score: %2d/10  %s  %s", r.Scenario.name, r.Grade.Score, marker, r.Grade.Reasoning)
		for _, s := range r.Grade.Strengths {
			t.Logf("  + %s", s)
		}
		for _, w := range r.Grade.Weaknesses {
			t.Logf("  - %s", w)
		}
		fmt.Println()
	}

	if graded > 0 {
		t.Logf("Average score: %.1f/10 (%d scenarios graded)", float64(total)/float64(graded), graded)
	}

	require.True(t, pass, "one or more prompts scored below 5/10")
}
